functions.begins_with:
_Bool begins_with(const char *str, const char *prefix)
{
    u64 i = 0;
    while (1)
    {
        if (prefix[i] == '\0')
            return 1;
        if (str[i] == '\0')
            return prefix[i] == '\0';
        if (str[i] != prefix[i])
            return 0;
        i++;
    }
}

