void trusted_utils_sig_to_str(const u8 *sig, char *out)
{
    for (int charpos = 0; charpos < 16; charpos++)
    {
        char val1 = (sig[charpos] >> 4) & 0x0f;
        char val2 = sig[charpos] & 0x0f;
        ((void)sizeof((val1 >= 0 && val1 < 16) ? 1 : 0), __extension__({
             if (val1 >= 0 && val1 < 16)
                 ;
             else
                 __assert_fail(
                     "val1 >= 0 && val1 < 16",
                     "/home/bbzs/code/reporeflectrust/data/project/CBench/impcheck/src/trusted/trusted_utils.c", 161,
                     __extension__ __PRETTY_FUNCTION__);
         }));
        ((void)sizeof((val2 >= 0 && val2 < 16) ? 1 : 0), __extension__({
             if (val2 >= 0 && val2 < 16)
                 ;
             else
                 __assert_fail(
                     "val2 >= 0 && val2 < 16",
                     "/home/bbzs/code/reporeflectrust/data/project/CBench/impcheck/src/trusted/trusted_utils.c", 162,
                     __extension__ __PRETTY_FUNCTION__);
         }));
        out[2 * charpos + 0] = val1 >= 10 ? 'a' + val1 - 10 : '0' + val1;
        out[2 * charpos + 1] = val2 >= 10 ? 'a' + val2 - 10 : '0' + val2;
    }
    out[16 * 2] = '\0';
}

functions.trusted_utils_str_to_sig:
_Bool trusted_utils_str_to_sig(const char *str, u8 *out)
{
    for (int bytepos = 0; bytepos < 16; bytepos++)
    {
        const char *hex_pair = str + bytepos * 2;
        char hex1 = hex_pair[0];
        char hex2 = hex_pair[1];
        int byte = 16 * (hex1 >= '0' && hex1 <= '9' ? hex1 - '0' : 10 + hex1 - 'a') +
                   (hex2 >= '0' && hex2 <= '9' ? hex2 - '0' : 10 + hex2 - 'a');
        if (byte < 0 || byte >= 256)
            return 0;
        out[bytepos] = (u8)byte;
    }
    return 1;
}

