functions.append_integer:
void append_integer()
{
    if (header)
    {
        if (nb_vars == -1)
        {
            nb_vars = num;
            trusted_utils_write_int(nb_vars, f_out);
        }
        else if (nb_cls == -1)
        {
            nb_cls = num;
            trusted_utils_write_int(nb_cls, f_out);
            header = 0;
        }
        else
            abort();
        num = 0;
        began_num = 0;
        return;
    }
    const int lit = sign * num;
    if (lit == 0)
        nb_read_cls++;
    num = 0;
    sign = 1;
    began_num = 0;
    if (data->size == data->capacity)
        output_literal_buffer();
    int_vec_push(data, lit);
}

functions.process:
_Bool process(char c)
{
    if (comment && c != '\n' && c != '\r')
        return 0;
    signed char uc = *((signed char *)&c);
    switch (uc)
    {
    case (-1):
        input_finished = 1;
        return 1;
    case '\n':
    case '\r':
        comment = 0;
        if (began_num)
            append_integer();
        break;
    case 'p':
        header = 1;
        break;
    case 'c':
        if (!header)
            comment = 1;
        break;
    case ' ':
        if (began_num)
            append_integer();
        break;
    case '-':
        sign = -1;
        began_num = 1;
        break;
    case '0':
    case '1':
    case '2':
    case '3':
    case '4':
    case '5':
    case '6':
    case '7':
    case '8':
    case '9':
        num = num * 10 + (c - '0');
        began_num = 1;
        break;
    default:
        break;
    }
    return 0;
}

functions.tp_init:
void tp_init(const char *filename, FILE *out)
{
    siphash_init(SECRET_KEY);
    f = fopen(filename, "r");
    f_out = out;
    data = int_vec_init((1 << 14));
}

functions.tp_parse:
_Bool tp_parse(u8 **sig)
{
    while (1)
    {
        int c_int = fgetc_unlocked(f);
        if (process((char)c_int))
            break;
    }
    if (began_num)
        append_integer();
    if (data->size > 0)
        output_literal_buffer();
    siphash_pad(2);
    *sig = siphash_digest();
    trusted_utils_write_sig(*sig, f_out);
    return input_finished && !input_invalid;
}

functions.compute_clause_signature:
void compute_clause_signature(u64 id, const int *lits, int nb_lits, u8 *out)
{
    siphash_reset();
    siphash_update((u8 *)&id, sizeof(u64));
    siphash_update((u8 *)lits, nb_lits * sizeof(int));
    siphash_update(formula_signature, 16);
    const u8 *hash_out = siphash_digest();
    trusted_utils_copy_bytes(out, hash_out, 16);
}

