functions.int_vec_push:
void int_vec_push(struct int_vec *vec, int elem)
{
    if (vec->size == vec->capacity)
    {
        u64 new_cap = vec->capacity * 1.3;
        if (new_cap < vec->capacity + 1)
            new_cap = vec->capacity + 1;
        int_vec_reserve(vec, new_cap);
    }
    vec->data[vec->size++] = elem;
}

