functions.tc_run:
int tc_run(_Bool check_model, _Bool lenient)
{
    clock_t start = clock();
    u64 nb_produced = 0, nb_imported = 0, nb_deleted = 0;
    _Bool reported_error = 0;
    while (1)
    {
        int c = trusted_utils_read_char(input);
        if (c == 'a')
        {
            const u64 id = trusted_utils_read_ul(input);
            const int nb_lits = trusted_utils_read_int(input);
            read_literals(nb_lits);
            const int nb_hints = trusted_utils_read_int(input);
            read_hints(nb_hints);
            const _Bool share = trusted_utils_read_bool(input);
            _Bool res = top_check_produce(id, buf_lits->data, nb_lits, buf_hints->data, nb_hints, share ? buf_sig : 0);
            say(res);
            if (share)
                trusted_utils_write_sig(buf_sig, output);
            nb_produced++;
        }
        else if (c == 'i')
        {
            const u64 id = trusted_utils_read_ul(input);
            const int nb_lits = trusted_utils_read_int(input);
            read_literals(nb_lits);
            trusted_utils_read_sig(buf_sig, input);
            _Bool res = top_check_import(id, buf_lits->data, nb_lits, buf_sig);
            say(res);
            nb_imported++;
        }
        else if (c == 'd')
        {
            const int nb_hints = trusted_utils_read_int(input);
            read_hints(nb_hints);
            _Bool res = top_check_delete(buf_hints->data, nb_hints);
            say(res);
            nb_deleted += nb_hints;
        }
        else if (c == 'L')
        {
            const int nb_lits = trusted_utils_read_int(input);
            read_literals(nb_lits);
            for (int i = 0; i < nb_lits; i++)
                top_check_load(buf_lits->data[i]);
        }
        else if (c == 'B')
        {
            nb_vars = trusted_utils_read_int(input);
            top_check_init(nb_vars, check_model, lenient);
            trusted_utils_read_sig(formula_sig, input);
            top_check_commit_formula_sig(formula_sig);
            say_with_flush(1);
        }
        else if (c == 'E')
        {
            say_with_flush(top_check_end_load());
        }
        else if (c == 'V')
        {
            _Bool res = top_check_validate_unsat(buf_sig);
            say(res);
            trusted_utils_write_sig(buf_sig, output);
            fflush_unlocked(output);
            if (res)
                trusted_utils_log("UNSAT validated");
        }
        else if (c == 'M')
        {
            const int model_size = trusted_utils_read_int(input);
            int *model = trusted_utils_malloc(sizeof(int) * model_size);
            trusted_utils_read_ints(model, model_size, input);
            _Bool res = top_check_validate_sat(model, model_size, buf_sig);
            say(res);
            trusted_utils_write_sig(buf_sig, output);
            fflush_unlocked(output);
            if (res)
                trusted_utils_log("SAT validated");
            free(model);
        }
        else if (c == 'T')
        {
            say_with_flush(1);
            break;
        }
        else
        {
            trusted_utils_log_err("Invalid directive!");
            break;
        }
        if (__builtin_expect(!top_check_valid(), 0))
        {
            if (!reported_error)
            {
                trusted_utils_log_err(trusted_utils_msgstr);
                reported_error = 1;
            }
        }
    }
    float elapsed = (float)(clock() - start) / ((__clock_t)1000000);
    snprintf(trusted_utils_msgstr, 512, "cpu:%.3f prod:%lu imp:%lu del:%lu", elapsed, nb_produced, nb_imported,
             nb_deleted);
    trusted_utils_log(trusted_utils_msgstr);
    return 0;
}

