functions.hash_table_insert:
_Bool hash_table_insert(struct hash_table *ht, u64 key, void *val)
{
    if (key == 0)
        return 0;
    if (ht->size == ht->max_size)
    {
        if (!realloc_table(ht))
            return 0;
        if (ht->size >= ht->max_size)
            return 0;
    }
    u64 idx;
    if (find_entry(ht, key, &idx))
        return 0;
    if (!cell_empty(&ht->data[idx]))
        return 0;
    struct hash_table_entry *entry = &ht->data[idx];
    entry->key = key;
    entry->val = val;
    ht->size++;
    return 1;
}

functions.hash_table_delete:
_Bool hash_table_delete(struct hash_table *ht, u64 key)
{
    u64 idx;
    if (!find_entry(ht, key, &idx))
        return 0;
    if (!handle_gap(ht, idx))
        return 0;
    ht->size--;
    return 1;
}

functions.hash_table_delete_last_found:
_Bool hash_table_delete_last_found(struct hash_table *ht)
{
    if (!handle_gap(ht, ht->last_found_idx))
        return 0;
    ht->size--;
    return 1;
}
